"""Registration, discovery, lookup and export."""

from __future__ import annotations

import importlib
import io
import os
import re

from xport.formats.base import Context, Format, OptionError, RegistryError, UnknownFormatError

_KEY = re.compile(r"[a-z][a-z0-9]*\Z")
_BOOL = {"true": True, "yes": True, "on": True, "1": True, "false": False, "no": False, "off": False, "0": False}
_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_.-]*\Z")
_WHOLE = re.compile(r"[+-]?[0-9]+\Z")
_SKIP = ("base", "registry", "common")

_by_key: dict = {}
_owner: dict = {}
_instances: list = []
_state = {"done": False, "busy": False}


def register(cls):
    """Class decorator: registers one instance under its name and aliases."""
    module = cls.__module__
    keys = [cls.name, *cls.aliases]
    claimed: dict = {}
    for key in keys:
        if not isinstance(key, str) or not _KEY.match(key):
            raise RegistryError(f"format name '{key}' in {module} is not a valid name")
        earlier = _owner.get(key) or claimed.get(key)
        if earlier is not None:
            raise RegistryError(f"format name '{key}' is claimed by {earlier} and {module}")
        claimed[key] = module
    instance = cls()
    for key in keys:
        _by_key[key] = instance
        _owner[key] = module
    _instances.append(instance)
    return cls


def discover() -> None:
    """Imports every plugin module of this package, once."""
    if _state["done"] or _state["busy"]:
        return
    _state["busy"] = True
    try:
        here = os.path.dirname(os.path.abspath(__file__))
        names = sorted(
            f[:-3] for f in os.listdir(here)
            if f.endswith(".py") and not f.startswith("_") and f[:-3] not in _SKIP
            and os.path.isfile(os.path.join(here, f))
        )
        for name in names:
            importlib.import_module(f"xport.formats.{name}")
        _state["done"] = True
    finally:
        _state["busy"] = False


def _ordered() -> list:
    discover()
    return sorted(_instances, key=lambda f: (f.order, f.name))


def lookup(name: str) -> Format:
    discover()
    found = _by_key.get(name.strip().lower())
    if found is None:
        known = ", ".join(f.name for f in _ordered())
        raise UnknownFormatError(f"unknown format '{name}' (known: {known})")
    return found


def resolve(name: str) -> str:
    return lookup(name).name


def list_formats() -> list:
    return [(f.name, tuple(f.aliases), f.summary) for f in _ordered()]


def _convert(invoked: str, opt, text: str):
    where = f"option '{opt.name}' of format '{invoked}'"
    kind = opt.kind
    if kind == "bool":
        value = _BOOL.get(text.lower())
        if value is None:
            raise OptionError(f"{where} takes true or false, not '{text}'")
        return value
    if kind == "int":
        if not _WHOLE.match(text):
            raise OptionError(f"{where} takes a whole number, not '{text}'")
        n = int(text)
        if opt.low is not None and n < opt.low:
            raise OptionError(f"{where} must be at least {opt.low}")
        if opt.high is not None and n > opt.high:
            raise OptionError(f"{where} must be at most {opt.high}")
        return n
    if kind == "char":
        if text in ("tab", "\\t"):
            return "\t"
        if text == "space":
            return " "
        if len(text) != 1:
            raise OptionError(f"{where} takes a single character, not '{text}'")
        return text
    if kind == "choice":
        if text not in opt.choices:
            raise OptionError(f"{where} takes one of {'|'.join(opt.choices)}, not '{text}'")
        return text
    if kind == "name":
        if not _NAME.match(text):
            raise OptionError(f"{where} takes a name (letters, digits, _ . -), not '{text}'")
        return text
    return text


def _parse(fmt: Format, invoked: str, pairs):
    specs = fmt.options
    known = {opt.name for opt in specs}
    raw = {}
    for pair in pairs:
        key, sep, value = pair.partition("=")
        key = key.strip()
        if not sep or not key:
            raise OptionError(f"option '{pair}' is not key=value")
        if key not in known:
            names = ", ".join(opt.name for opt in specs) or "none"
            raise OptionError(f"format '{invoked}' has no option '{key}' (options: {names})")
        raw[key] = value
    values = {}
    for opt in specs:
        values[opt.name] = _convert(invoked, opt, raw[opt.name]) if opt.name in raw else opt.default
    return values, frozenset(raw)


def export(table, fmt_name: str, options=(), out=None) -> None:
    """Writes table to the text stream out in the named format."""
    fmt = lookup(fmt_name)
    values, given = _parse(fmt, fmt_name, options)
    ctx = Context(fmt_name, values, given, out)
    fmt.check(ctx)
    fmt.write(table, ctx)


def export_text(table, fmt_name: str, options=()) -> str:
    buf = io.StringIO(newline="")
    export(table, fmt_name, options, buf)
    return buf.getvalue()
