"""Helpers shared by several plugins."""

from __future__ import annotations

from datetime import datetime
from decimal import ROUND_HALF_EVEN, Decimal

NUMERIC = ("int", "dec")


def quant(value: Decimal, scale: int) -> str:
    return str(value.quantize(Decimal(1).scaleb(-scale), rounding=ROUND_HALF_EVEN))


def wall(value: datetime) -> str:
    return value.strftime("%Y-%m-%d %H:%M:%S")


def cell(col, value, tag_sep, bools=("true", "false")):
    """Text of a non-missing value: the common rules of the text formats."""
    kind = col.type
    if kind == "tags":
        return tag_sep.join(value)
    if kind == "str":
        return value
    if kind == "bool":
        return bools[0] if value else bools[1]
    if kind == "int":
        return str(value)
    if kind == "dec":
        return quant(value, col.scale)
    if kind == "date":
        return value.isoformat()
    return wall(value)
